// CDLGRAVESTONEDOJIOpen opens a live [CDLGRAVESTONEDOJIStream] on a warm-up
// history, oldest bar first, and returns it with its value at the last history
// bar, the value [Core.CDLGRAVESTONEDOJI] writes there.
//
// inOpen, inHigh, inLow and inClose are the histories, of one length.
//
// The error is [InsufficientHistory] for a history of at most
// [Core.CDLGRAVESTONEDOJILookback] bars, [OutOfRangeEndIndex] for one longer
// than [IndexMax]+1 bars, and [BadParam] for histories of different lengths.
func (c *Core) CDLGRAVESTONEDOJIOpen(inOpen, inHigh, inLow, inClose []float64) (*CDLGRAVESTONEDOJIStream, int32, error) {
	sp, err := c.cdlgravestonedojiOpenInternal(inOpen, inHigh, inLow, inClose, 0)
	if err != nil {
		return nil, 0, err
	}
	return sp, sp.cur_outInteger, nil
}

// CDLGRAVESTONEDOJIOpenAndFill opens a stream as [Core.CDLGRAVESTONEDOJIOpen]
// does and also writes the outputs over the whole history, as
// [Core.CDLGRAVESTONEDOJI] writes them for bars 0 through len(inOpen)-1,
// returning that range.
//
// Each output must hold len(inOpen) minus [Core.CDLGRAVESTONEDOJILookback]
// values and share no memory with an input or another output.
//
// The errors are those of [Core.CDLGRAVESTONEDOJIOpen], and [BadParam] for an
// output that is empty, too short or sharing memory.
func (c *Core) CDLGRAVESTONEDOJIOpenAndFill(inOpen, inHigh, inLow, inClose []float64, outInteger []int32) (*CDLGRAVESTONEDOJIStream, OutRange, error) {
	if len(inOpen) > IndexMax+1 {
		return nil, OutRange{}, OutOfRangeEndIndex
	}
	lookback := int(c.cdlgravestonedojiLookback())
	if lookback < 0 {
		return nil, OutRange{}, BadParam
	}
	if len(inHigh) != len(inOpen) {
		return nil, OutRange{}, BadParam
	}
	if len(inLow) != len(inOpen) {
		return nil, OutRange{}, BadParam
	}
	if len(inClose) != len(inOpen) {
		return nil, OutRange{}, BadParam
	}
	outLen := max(len(inOpen)-lookback, 0)
	if len(outInteger) == 0 || len(outInteger) < outLen {
		return nil, OutRange{}, BadParam
	}
	var outBegIdx, outNBElement int32
	sp, err := c.cdlgravestonedojiOpenAndFillInternal(inOpen, inHigh, inLow, inClose, 0, &outBegIdx, &outNBElement, outInteger)
	if err != nil {
		return nil, OutRange{}, err
	}
	return sp, OutRange{BegIdx: int(outBegIdx), NBElement: int(outNBElement)}, nil
}
